from taf.gnb.oam.ne3s.ws.components.PM import PMv2

from taf.gnb.oam.ne3s.ws.interfaces.v5G19A import v5G19A


class v5G20B(v5G19A):
    connection = None

    def __init__(self, connection_details):
        """
        :param connection_details taf.gnb.oam.ne3s.ws.provider.NE3SConnectionDetails: path to the SW package in .zip format
        """

        super(v5G20B, self).__init__(connection_details)
        self.pm = PMv2(connection=self.connection)
